search:[{name:'id',label:'Research log ID',required:true},{name:'projectId',label:'Project',type:'select',options:()=>projectOpts()},{name:'personId',label:'Person',type:'select',options:()=>personOpts()},{name:'date',label:'Search date',type:'date'},{name:'question',label:'Research question',required:true,full:true},{name:'repository',label:'Repository / collection'},{name:'query',label:'Search terms and coverage',full:true},{name:'result',label:'Result',type:'select',options:['Found','Not found','Partial','Blocked','Not started']},{name:'sourceId',label:'Related source',type:'select',options:()=>sourceOpts()},{name:'findings',label:'Findings and search limitations',type:'textarea',full:true},{name:'next',label:'Next action',type:'textarea',full:true}],
claim:[{name:'id',label:'Claim ID',required:true},{name:'projectId',label:'Project',type:'select',options:()=>projectOpts()},{name:'personId',label:'Person',type:'select',options:()=>personOpts()},{name:'statement',label:'Specific research claim',required:true,full:true},{name:'status',label:'Resolution',type:'select',options:['Unreviewed','Supported','Probable','Unresolved conflict','Rejected','Needs research']},{name:'confidence',label:'Confidence',type:'select',options:confidence},{name:'supportIds',label:'Sources supporting this claim',type:'sourcesMulti',full:true},{name:'opposeIds',label:'Sources conflicting with this claim',type:'sourcesMulti',full:true},{name:'reasoning',label:'Evidence assessment and reasoning',type:'textarea',full:true},{name:'next',label:'What evidence is still needed?',type:'textarea',full:true}],
