event:[{name:'id',label:'Event ID',required:true},{name:'projectId',label:'Project',type:'select',options:()=>projectOpts()},{name:'personId',label:'Person',type:'select',options:()=>personOpts()},{name:'date',label:'Date / year (as recorded)'},{name:'title',label:'Event',required:true},{name:'place',label:'Location'},{name:'sourceId',label:'Evidence source',type:'select',options:()=>sourceOpts()},{name:'notes',label:'Notes',type:'textarea',full:true}],
household:[{name:'id',label:'Household ID',required:true},{name:'projectId',label:'Project',type:'select',options:()=>projectOpts()},{name:'title',label:'Household label',required:true},{name:'date',label:'Date / census year'},{name:'place',label:'Location'},{name:'memberIds',label:'People in household',type:'peopleMulti',full:true},{name:'sourceId',label:'Source',type:'select',options:()=>sourceOpts()},{name:'notes',label:'Relationship and identification notes',type:'textarea',full:true}],
