expense:[{name:'id',label:'Expense ID',required:true},{name:'projectId',label:'Project',type:'select',options:()=>projectOpts()},{name:'date',label:'Expense date',type:'date'},{name:'vendor',label:'Payee or provider',required:true},{name:'category',label:'Category',type:'select',options:['Archive / record fee','Travel','Subscription','Printing','Supplies','Postage','Appraisal research','Other']},{name:'amount',label:'Amount ($)',type:'number',step:'.01',min:'0',required:true},{name:'notes',label:'Description / receipt reference',type:'textarea',full:true}],
