function projectOpts(){return [{value:'',label:'Personal / unassigned'},...state.projects.map(p=>({value:p.id,label:`${p.title} (${p.id})`}))]}
function personOpts(){return [{value:'',label:'Select person'},...state.people.map(p=>({value:p.id,label:`${p.name} (${p.id})`}))]}
function sourceOpts(){return [{value:'',label:'Select source'},...state.sources.map(p=>({value:p.id,label:`${p.title} (${p.id})`}))]}
function customModal(title,body,onSubmit,submitLabel='Save'){modalAction=onSubmit;$('modalTitle').textContent=title;$('modalBody').innerHTML=`<form id="editorForm">${body}<div class="modal-foot"><button type="button" class="btn" data-close>Cancel</button><button type="submit" class="btn primary">${esc(submitLabel)}</button></div></form>`;$('modalBackdrop').classList.remove('hidden');document.body.style.overflow='hidden';$('editorForm').querySelector('input:not([type=hidden]),select,textarea')?.focus()}
function closeModal(){modalAction=null;$('modalBackdrop').classList.add('hidden');document.body.style.overflow=''}
async function db(){if(fileDb)return fileDb;fileDb=await new Promise((resolve,reject)=>{const req=indexedDB.open(FILE_DB,1);req.onupgradeneeded=()=>req.result.createObjectStore('files',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});return fileDb}
async function putFile(id,f){const d=await db();await new Promise((resolve,reject)=>{const tx=d.transaction('files','readwrite');tx.objectStore('files').put({id,name:f.name,type:f.type||'application/octet-stream',blob:f});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function getFile(id){const d=await db();return await new Promise((resolve,reject)=>{const t=d.transaction('files','readonly');const q=t.objectStore('files').get(id);q.onsuccess=()=>resolve(q.result||null);q.onerror=()=>reject(q.error)})}
async function allFiles(){const d=await db();return await new Promise((resolve,reject)=>{const q=d.transaction('files','readonly').objectStore('files').getAll();q.onsuccess=()=>resolve(q.result||[]);q.onerror=()=>reject(q.error)})}
async function deleteFile(id){const d=await db();await new Promise((resolve,reject)=>{const tx=d.transaction('files','readwrite');tx.objectStore('files').delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
function editor(type,id=''){const old=id?record(type,id):null;let values=old?{...old}:{id:type==='source'?'':idFor(type),category:type==='source'?'o':'',projectId:state.settings.activeProject||'',status:type==='source'?'—':type==='person'?'Unreviewed':type==='task'?'Not started':type==='project'?'Active':type==='claim'?'Unreviewed':'',date:today(),rate:state.settings.defaultRate,billable:false,peopleIds:[],supportIds:[],opposeIds:[],memberIds:[]};if(type==='session'&&old){values.date=isoLocal(old.startedAt).slice(0,10);values.minutes=Number(mins(old.durationMs).toFixed(2))}if(type==='project'&&!old)values.type='Personal genealogy';const fields=defs[type];if(!fields){toast('Unknown editor');return}const timerBridge=type==='session'&&!old?`<div class="callout" style="margin-bottom:16px"><strong>Track this session with the timer:</strong> enter the project, person, work type and task, then use the timer instead of typing minutes. <button class="btn small" type="button" id="useSessionTimer" style="margin-left:9px">${state.timer.mode==='idle'?'▶ Start timer from this entry':'■ Finish active timer'}</button></div>`:'';const html=`${timerBridge}<div class="form-grid">${fields.map(f=>f.type==='file'?`<div class="field full"><label for="f-localFile">${esc(f.label)}</label><input type="file" id="f-localFile" name="localFile" accept=".pdf,.jpg,.jpeg,.png,.webp,.txt,.doc,.docx,.tif,.tiff">${values.fileName?`<span class="hint">Current attachment: ${esc(values.fileName)} (replacing does not change the Drive original)</span>`:''}<span class="hint">${esc(f.hint||'')}</span></div>`:field({...f,readonly:f.name==='id'&&(!!old||type==='source'),options:typeof f.options==='function'?f.options():f.options},values[f.name])).join('')}</div>`;
customModal(`${old?'Edit':'Add'} ${type}`,html,async fd=>{const obj={...values};for(const f of fields){if(f.type==='file')continue;if(f.type==='checkbox')obj[f.name]=fd.has(f.name);else if(f.type==='peopleMulti'||f.type==='sourcesMulti')obj[f.name]=fd.getAll(f.name);else if(f.type==='number')obj[f.name]=Number(fd.get(f.name)||0);else obj[f.name]=String(fd.get(f.name)||'').trim()}
if(type==='source'&&!old){
 const proposed=nextPersonSourceId(obj.personId,obj.category);
 if(!proposed){toast('Select a primary person with a numbered ID before saving the source');return false}
 obj.id=proposed;
 obj.peopleIds=[...new Set([obj.personId,...(obj.peopleIds||[])])];
}
if(!obj.id||!(obj.name||obj.title||obj.statement||obj.question||type==='relationship'||type==='session'||type==='event'||type==='household'||type==='expense')){toast('Complete all required fields');return false}
if(state[collection[type]].some(x=>x.id===obj.id&&x!==old)){toast('This record ID is already in use');return false}
if(type==='relationship'&&(!obj.fromId||!obj.toId||obj.fromId===obj.toId)){toast('Choose two different people');return false}
if(type==='source'&&obj.status==='R'&&(!obj.citation||(!obj.url&&!obj.downloadVerified&&!fd.get('localFile')?.size)||!obj.notes)){toast('Review needs a citation, an original location or saved copy, and documented findings');return false}
if(type==='source'&&obj.status==='Cx'&&!obj.notes){toast('Document the unresolved conflict in the findings field');return false}
if(type==='session'){if(obj.workClass==='Assistant-only')obj.billable=false;if(!obj.minutes||obj.minutes<=0){toast('Duration must be greater than zero');return false}obj.durationMs=Math.round(obj.minutes*60000);obj.startedAt=new Date(obj.date+'T12:00:00').toISOString();obj.endedAt=obj.startedAt;obj.method=old?.method||'manual';delete obj.minutes;delete obj.date}
const uploaded=fd.get('localFile');if(type==='source'&&uploaded instanceof File&&uploaded.size){try{await putFile(obj.id,uploaded);obj.fileName=uploaded.name;obj.fileType=uploaded.type}catch(e){toast('Attachment could not be saved; record was not changed');return false}}
obj.updatedAt=new Date().toISOString();if(!old){obj.createdAt=obj.updatedAt;state[collection[type]].push(obj)}else Object.assign(old,obj);save(`${old?'Updated':'Created'} ${type} ${obj.id}`);toast(`${type[0].toUpperCase()+type.slice(1)} saved`);render();return true},old?'Save changes':'Create record');
if(type==='source'&&!old){
 const idInput=$('f-id'),personInput=$('f-personId'),categoryInput=$('f-category');
 const updatePreview=()=>{
  if(!idInput||!personInput||!categoryInput)return;
  idInput.value=nextPersonSourceId(personInput.value,categoryInput.value);
  idInput.placeholder=personInput.value?'Unable to generate ID':'Select primary person to generate an ID';
 };
 personInput?.addEventListener('change',updatePreview);
 categoryInput?.addEventListener('change',updatePreview);
 updatePreview();
}
}
function workSummary(){const ss=scope('session');return {hours:ss.filter(s=>s.workClass!=='Assistant-only').reduce((a,s)=>a+mins(s.durationMs)/60,0),assistantHours:ss.filter(s=>s.workClass==='Assistant-only').reduce((a,s)=>a+mins(s.durationMs)/60,0),billable:ss.reduce((a,s)=>a+(s.billable&&s.workClass!=='Assistant-only'?mins(s.durationMs)/60*Number(s.rate||0):0),0),expenses:scope('expense').reduce((a,e)=>a+Number(e.amount||0),0)}}
function legacyResetBanner(){
 const base=state.legacyArchive?.baselineDate;
 return '<section class="card" style="margin:0 0 16px"><div class="split flex-wrap"><div><h3 class="section-title">Timesheet baseline</h3><p class="muted small-text">'+(base?'Fresh tracking baseline active since '+esc(base)+'. Historical records are archived.':'Legacy sessions are still included in your active timesheet. Archive them to start fresh on November 7, 2026.')+'</p></div>'+(base?'<span class="pill">Archive active</span>':'<button class="btn primary" id="archiveLegacyButton">Archive legacy & start fresh — Nov 7, 2026</button>')+'</div></section>';
}
function renderDashboard(){const all=workSummary();let ts=scope('task');let unresolved=scope('claim').filter(x=>x.status==='Unresolved conflict'||x.confidence==='Disputed');let pending=scope('source').filter(x=>['—','F','P','PW','Cx','D'].includes(x.status));const latest=dateSort(state.history,'at').slice(0,5);
content(intro('Research workspace','Continue your investigations, monitor evidence gaps, and log working time.',`<button class="btn" data-nav="visuals">Explore relationships →</button>`)+legacyResetBanner()+`<div class="grid stats">${stat('Research hours',fmt(all.hours,1),'Saved across '+scope('session').length+' sessions')}${stat('People',scope('person').length,'Permanent R00 records')}${stat('Open source work',pending.length,'Unreviewed / blocked / disputed')}${stat('Evidence conflicts',unresolved.length,'Claims needing resolution')}</div>`+
`<div class="grid cols-2"><section class="card"><div class="split block-heading"><h3 class="section-title">Research priorities</h3>${newBtn('task','New task')}</div>${ts.filter(t=>t.status!=='Completed').length?ts.filter(t=>t.status!=='Completed').sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999')).slice(0,6).map(t=>`<div class="soft-row"><div><strong>${esc(t.title)}</strong><small>${esc(t.id)} · ${esc(label('project',t.projectId))} ${t.dueDate?' · Due '+esc(t.dueDate):''}</small></div>${uiBadge(t.status)} <button class="btn small" data-edit="task:${esc(t.id)}">Open</button></div>`).join(''):empty('No open tasks','Add a research task or create one from an unfinished record.','task')}</section>`+
`<section class="card"><div class="split block-heading"><h3 class="section-title">Sources needing attention</h3><button class="btn small" data-nav="sources">All sources</button></div>${pending.length?pending.slice(0,6).map(s=>`<div class="soft-row"><div><strong>${esc(s.title)}</strong><small>${esc(s.id)} · ${esc(statusLabels[s.status]||s.status)}</small></div>${uiBadge(s.status)} <button class="btn small" data-edit="source:${esc(s.id)}">Review</button></div>`).join(''):empty('No open sources','Add the first source record or change the project filter.','source')}</section></div>`+
`<div class="grid cols-2" style="margin-top:17px"><section class="card"><div class="split block-heading"><h3 class="section-title">Current projects</h3>${newBtn('project','New project')}</div>${scope('project').length?scope('project').slice(0,6).map(p=>{const n=state.people.filter(x=>x.projectId===p.id).length;return `<div class="soft-row"><div><strong>${esc(p.title)}</strong><small>${esc(p.id)} · ${n} people · ${esc(p.branch||p.type)}</small></div>${uiBadge(p.status)} <button class="btn small" data-edit="project:${esc(p.id)}">Open</button></div>`}).join(''):empty('Start your first project','Create a personal genealogy branch or a client research case.','project')}</section>`+
`<section class="card"><h3 class="section-title block-heading">Quick actions</h3><div class="grid cols-2"><button class="btn" data-new="person">+ Register person</button><button class="btn" data-new="source">+ Add source</button><button class="btn" data-new="search">+ Log a search</button><button class="btn" data-new="claim">+ Record a claim</button><button class="btn" data-new="relationship">+ Add relationship</button><button class="btn" data-nav="reports">↗ Build a report</button></div><div class="callout" style="margin-top:17px">A sourced record is not proof that an identity is correct. Keep conflicting claims visible until the evidence is assessed.</div></section></div>`+
`<section class="card" style="margin-top:17px"><div class="split block-heading"><h3 class="section-title">Recent activity</h3><span class="pill">Saved locally</span></div>${latest.length?latest.map(h=>`<div class="soft-row"><div><strong>${esc(h.note)}</strong><small title="${esc(h.at||'')}">${esc(activityTimestamp(h.at))}</small></div></div>`).join(''):'<p class="muted small-text">No activity yet. Create a record to begin.</p>'}</section>`)}

// Archive-only reset: this changes the timesheet baseline without deleting family records or source documents.
function archiveLegacyTimesheet(){
  if(state.timer.mode!=='idle'){toast('Finish or stop the running timer before resetting the timesheet');return}
  if(state.legacyArchive?.baselineDate){toast('The fresh tracking baseline is already active');return}
  const oldTasks=state.tasks.filter(t=>/^T-LEGACY-/i.test(String(t.id||'')));
  const oldSessions=[...state.sessions]; // All existing sessions become historical, including verified ones.
  if(!confirm('Start fresh timesheet tracking on November 7, 2026? This archives '+oldSessions.length+' existing sessions and '+oldTasks.length+' legacy cleanup tasks. Genealogy research, files, people, projects, and expenses stay unchanged.'))return;
  const archivedAt=new Date().toISOString();
  state.legacyArchive={baselineDate:'2026-11-07',archivedAt,tasks:oldTasks.map(t=>({...t,archivedAt,archiveReason:'Historical — insufficient evidence or legacy review'})),sessions:oldSessions.map(x=>({...x,archivedAt,archiveReason:'Historical session — excluded from new baseline totals'}))};
  state.tasks=state.tasks.filter(t=>!/^T-LEGACY-/i.test(String(t.id||'')));
  state.sessions=[];
  save('Archived legacy timesheet and started fresh baseline 2026-11-07');
  navigate('timesheet');
  toast('Legacy records archived. New timesheet baseline is November 7, 2026.');
}
function historicalTimesheetHtml(){
  const a=state.legacyArchive||{tasks:[],sessions:[]};
  const old=a.sessions||[],tasks=a.tasks||[];
  if(!a.baselineDate)return '<p class="muted small-text">No reset has been applied. Old time entries remain in active totals until you choose the archive action.</p>';
  return `<div class="callout"><strong>New tracking baseline: ${esc(a.baselineDate)}</strong><br>Historical sessions: ${old.length}. Archived legacy review tasks: ${tasks.length}. These entries are preserved in backup exports and excluded from new time totals.</div>
  ${old.length?compactRows(old,x=>`<tr><td>${esc(x.id)}</td><td>${esc(x.startedAt||x.date||'Date unverified')}</td><td>${esc(x.workType||'—')}</td><td>${x.durationMs==null?'Unverified':esc(duration(x.durationMs))}</td></tr>`,['ID','Original time/date','Activity','Stored duration']):'<p class="muted small-text">No archived sessions.</p>'}
  ${tasks.length?'<h4>Archived legacy cleanup tasks</h4>'+compactRows(tasks,x=>`<tr><td>${esc(x.id)}</td><td>${esc(x.title||'')}</td><td>Archived — insufficient evidence</td></tr>`,['ID','Legacy issue','Disposition']):''}`;
}

function renderTimesheet(){const s=workSummary();const sessions=dateSort(scope('session'),'startedAt').filter(x=>sessionFilter==='all'||(sessionFilter==='billable'?x.billable:!x.billable));const total=sessions.reduce((a,x)=>a+mins(x.durationMs)/60,0);
content(intro('Research timesheet','Track your work by person, branch, project and research activity. The timer stays visible above every section.',`${newBtn('session','Manual time entry')}${!state.legacyArchive?.baselineDate?'<button class="btn" id="archiveLegacyButton">Archive legacy & start fresh — Nov 7, 2026</button>':''}`)+`<div class="grid stats">${stat('Total hours',fmt(s.hours,2),'Research time')}${stat('Billable value',cash(s.billable),'Estimated value only')}${stat('Cash expenses',cash(s.expenses),'From expense ledger')}${stat('Logged sessions',scope('session').length,fmt(s.assistantHours,2)+' assistant-only hours recorded separately')}</div>`+
`<section class="card"><div class="split"><div><h3 class="section-title">Session history</h3><p class="muted small-text">Timer and manual entries share the same report.</p></div><div class="flex flex-wrap no-print"><select id="sessionFilter" aria-label="Filter time entries"><option value="all" ${sessionFilter==='all'?'selected':''}>All entries</option><option value="billable" ${sessionFilter==='billable'?'selected':''}>Billable only</option><option value="nonbillable" ${sessionFilter==='nonbillable'?'selected':''}>Nonbillable only</option></select><button class="btn small" data-export="sessions">Export CSV</button></div></div><div style="height:15px"></div>${sessions.length?compactRows(sessions,x=>`<tr><td><span class="main-cell">${esc(x.id)}</span><br><small>${esc(day(x.startedAt))}</small></td><td>${esc(label('project',x.projectId))}</td><td>${esc(x.branch||label('person',x.personId)||'—')}</td><td>${esc(x.workType)} · ${esc(x.workClass||'Hands-on')}<br><span class="muted">${esc(x.task)}</span></td><td>${esc(duration(x.durationMs))}</td><td>${x.billable?cash(mins(x.durationMs)/60*Number(x.rate||0)):'—'}</td><td>${actions('session',x.id)}</td></tr>`,['Session','Project','Branch / person','Work','Duration','Billable','Actions']):empty('No sessions yet','Start the timer above, or add a manual time entry.','session')}<p class="small-text muted">Showing ${fmt(total,2)} recorded elapsed hours in this view (assistant-only time may overlap with hands-on time). Personal work totals exclude assistant-only sessions.</p></section>`+ (state.legacyArchive?.baselineDate?`<section class="card" style="margin-top:16px"><details><summary><strong>Historical timesheet archive (excluded from current totals)</strong></summary><div style="margin-top:12px">${historicalTimesheetHtml()}</div></details></section>`:''))}
