$('main').addEventListener('input',e=>{if(e.target.id==='driveSearch'){driveSearch=e.target.value;const pos=e.target.selectionStart;render();const el=$('driveSearch');if(el){el.focus();el.setSelectionRange(pos,pos)}return}if(e.target.id==='recordSearch'){const sel=e.target.selectionStart;searchTerm=e.target.value;render();const ref=$('recordSearch');if(ref){ref.focus();ref.setSelectionRange(sel,sel)}}if(e.target.id==='visualZoom'){chartZoom=Number(e.target.value);const svg=document.querySelector('.graph-viewport svg');if(svg){const vb=svg.viewBox.baseVal;svg.setAttribute('width',Math.ceil(vb.width*chartZoom));svg.setAttribute('height',Math.ceil(vb.height*chartZoom))}}});
